$now = [DateTimeOffset]::Parse($env:QRK_NOW, [Globalization.CultureInfo]::InvariantCulture)
$openHour = 8
$closeHour = 17
$isWeekday = $now.DayOfWeek -notin @([DayOfWeek]::Saturday, [DayOfWeek]::Sunday)
if ($isWeekday -and $now.Hour -ge $openHour -and $now.Hour -lt $closeHour) {
    [Console]::Out.Write('Our support team is available today until 5:00 PM.')
} else {
    $next = $now.Date.AddDays(1)
    while ($next.DayOfWeek -in @([DayOfWeek]::Saturday, [DayOfWeek]::Sunday)) {
        $next = $next.AddDays(1)
    }
    [Console]::Out.Write(('Our support team will be available again {0} at 8:00 AM.' -f $next.ToString('dddd')))
}
